#include <print>
#include <vector>

int main() {
    std::vector<std::vector<int>> adj(4);
    adj[0].push_back(1);
    adj[1].push_back(0);
    adj[1].push_back(2);
    adj[2].push_back(1);
    adj[2].push_back(3);
    adj[3].push_back(2);
    for (int i = 0; i < 4; ++i) {
        std::print("{} 的好友:", i);
        for (int f : adj[i]) std::print(" {}", f);
        std::println("");
    }
    // 2 的名单变成 1 3，3 从空名单变成只有 2
    return 0;
}

